interactions.sample_code:
function bucketSort(A, B) {
  const n = 10;
  for (let i = 1; i <= n; i++) {
    const x = read(i);
    const b = Math.floor(n * x);   // half-open bucket [b/10, (b+1)/10)
    mark(b);
    // walk the chain to find the sorted insertion point
    let k = 0;
    while (k < listLength(b) && nodeAt(b, k) < x) {
      k++;
    }
    insertAt(b, k, x);
    note('placed ' + x + ' at position ' + k + ' of bucket ' + b);
  }
}

interactions.buggy_code:
function bucketSort(A, B) {
  const n = 10;
  for (let i = 1; i <= n; i++) {
    const x = read(i);
    // BUG 1: round() instead of floor() -- .78 lands in bucket 8, not 7
    const b = Math.round(n * x);
    mark(b);
    // BUG 2: always appends at the tail, so a chain can come out unsorted (.17 before .12)
    insertAt(b, listLength(b), x);
  }
}

